using UnityEngine;
namespace ApptyaKingdom {
 /// <summary>Temporary 3D blockout generator; replace primitives with original art assets.</summary>
 public class ProceduralKingdomBootstrap:MonoBehaviour {
  public int treeCount=55; Material grass,forest,stone,roof,wood,water,gold,leaf;
  void Awake(){MakeMaterials();Ground();Keep();Buildings();Forest();LightingCamera();if(ApptyaGameState.Instance==null)new GameObject("Apptya Game State").AddComponent<ApptyaGameState>();new GameObject("Apptya Runtime HUD").AddComponent<ApptyaRuntimeHud>();}
  Material M(string n,Color c){var sh=Shader.Find("Universal Render Pipeline/Lit");if(sh==null)sh=Shader.Find("Standard");return new Material(sh){name=n,color=c};}
  void MakeMaterials(){grass=M("Meadow",new Color(.23f,.40f,.24f));forest=M("Deep forest",new Color(.10f,.25f,.17f));stone=M("Limestone",new Color(.72f,.67f,.55f));roof=M("Blue slate",new Color(.12f,.22f,.35f));wood=M("Timber",new Color(.27f,.15f,.08f));water=M("River teal",new Color(.08f,.37f,.45f));gold=M("Royal gold",new Color(.85f,.61f,.22f));leaf=M("Leaf",new Color(.13f,.34f,.15f));}
  GameObject P(PrimitiveType t,string n,Vector3 p,Vector3 s,Material m){var g=GameObject.CreatePrimitive(t);g.name=n;g.transform.SetParent(transform,true);g.transform.position=p;g.transform.localScale=s;if(m)g.GetComponent<Renderer>().sharedMaterial=m;return g;}
  void Ground(){P(PrimitiveType.Cube,"Valley terrain",new Vector3(0,-.6f,0),new Vector3(44,1,44),grass);P(PrimitiveType.Cube,"River",new Vector3(0,-.03f,-8),new Vector3(44,.12f,3.5f),water);P(PrimitiveType.Cube,"Bridge",new Vector3(0,.08f,-8),new Vector3(4,.3f,4),stone);for(int i=0;i<7;i++)P(PrimitiveType.Sphere,"Rolling hill",new Vector3(-23+i*7,1.3f,17+(i%2)*3),new Vector3(12,5,8),forest);}
  void Keep(){P(PrimitiveType.Cube,"Keep foundation",new Vector3(0,.25f,2),new Vector3(8,.5f,6),stone);P(PrimitiveType.Cube,"Keep hall",new Vector3(0,2.1f,2),new Vector3(5.2f,3.3f,4.3f),stone);for(int x=-1;x<=1;x+=2)for(int z=0;z<=1;z++){Vector3 p=new Vector3(x*3.1f,2.2f,z==0?-.1f:4.2f);P(PrimitiveType.Cube,"Tower",p,new Vector3(1.55f,4.2f,1.55f),stone);P(PrimitiveType.Cylinder,"Tower roof",p+Vector3.up*2.65f,new Vector3(1.35f,.9f,1.35f),roof);P(PrimitiveType.Cube,"Gold trim",p+Vector3.up*1.75f,new Vector3(1.62f,.13f,1.62f),gold);}P(PrimitiveType.Cube,"Keep gate",new Vector3(0,1.05f,-.22f),new Vector3(1.25f,2.1f,.15f),wood);P(PrimitiveType.Cube,"Royal banner",new Vector3(0,5.3f,2),new Vector3(.16f,1.3f,.08f),gold);}
  void Buildings(){House("Lumber Camp",new Vector3(-8,.25f,1));House("Farmstead",new Vector3(8,.25f,1));House("Barracks",new Vector3(-7,.25f,7));House("Quarry",new Vector3(7,.25f,7));}
  void House(string n,Vector3 p){P(PrimitiveType.Cube,n+" walls",p+Vector3.up*.8f,new Vector3(2.7f,1.6f,2.3f),stone);P(PrimitiveType.Cube,n+" roof",p+Vector3.up*1.8f,new Vector3(3.1f,.35f,2.7f),roof);}
  void Forest(){var r=new System.Random(7391);for(int i=0;i<treeCount;i++){float x=(float)r.NextDouble()*36-18,z=(float)r.NextDouble()*34-15;if(Mathf.Abs(x)<5.5f&&z>-2&&z<8||z>-10&&z<-6)continue;float h=1.5f+(float)r.NextDouble()*1.4f;P(PrimitiveType.Cylinder,"Pine trunk",new Vector3(x,.2f,z),new Vector3(.22f,h,.22f),wood);P(PrimitiveType.Sphere,"Pine canopy",new Vector3(x,h*.85f+.3f,z),new Vector3(1.2f,h*1.2f,1.2f),leaf);}}
  void LightingCamera(){var l=new GameObject("Warm sun").AddComponent<Light>();l.type=LightType.Directional;l.intensity=1.15f;l.color=new Color(1,.86f,.68f);l.transform.rotation=Quaternion.Euler(48,-32,0);RenderSettings.ambientLight=new Color(.48f,.53f,.57f);var c=Camera.main;if(!c)c=new GameObject("Main Camera").AddComponent<Camera>();c.tag="MainCamera";c.transform.position=new Vector3(0,16,-23);c.transform.rotation=Quaternion.Euler(32,0,0);c.fieldOfView=42;c.backgroundColor=new Color(.35f,.55f,.62f);if(c.GetComponent<ApptyaCameraController>()==null)c.gameObject.AddComponent<ApptyaCameraController>();}
 }
}